-- Fill empty Argus quest POI point sets while retaining the 7.3.5 blob definitions.
-- Sources: TrinityCore 28153, then 52106 where the objective, map and phase context match.
-- VerifiedBuild 0 marks adapted 52106 coordinates because the local column is signed SMALLINT.
START TRANSACTION;

CREATE TEMPORARY TABLE argus_poi_definitions (
    QuestID INT NOT NULL, BlobIndex INT NOT NULL, Idx1 INT NOT NULL,
    ObjectiveIndex INT NOT NULL, QuestObjectiveID INT NOT NULL, QuestObjectID INT NOT NULL,
    MapID INT NOT NULL, WorldMapAreaId INT NOT NULL, Floor INT NOT NULL,
    Priority INT NOT NULL, Flags INT NOT NULL, WorldEffectID INT NOT NULL,
    PlayerConditionID INT NOT NULL, WoDUnk1 INT NOT NULL, AlwaysAllowMergingBlobs INT NOT NULL,
    PRIMARY KEY (QuestID, Idx1)
) ENGINE=InnoDB;


CREATE TEMPORARY TABLE argus_poi_coordinates (
    QuestID INT NOT NULL, Idx1 INT NOT NULL, Idx2 INT NOT NULL,
    X INT NOT NULL, Y INT NOT NULL, VerifiedBuild SMALLINT NOT NULL,
    PRIMARY KEY (QuestID, Idx1, Idx2)
) ENGINE=InnoDB;


-- Select whole coordinate sets so a partially populated local polygon is preserved.
SELECT p.QuestID, p.Idx1, p.Idx2, p.X, p.Y, p.VerifiedBuild
FROM argus_poi_coordinates AS p
JOIN argus_poi_definitions AS expected ON expected.QuestID = p.QuestID AND expected.Idx1 = p.Idx1
JOIN quest_poi AS b ON b.QuestID = expected.QuestID AND b.Idx1 = expected.Idx1
    AND b.BlobIndex = expected.BlobIndex
    AND b.ObjectiveIndex = expected.ObjectiveIndex AND b.QuestObjectiveID = expected.QuestObjectiveID
    AND b.QuestObjectID = expected.QuestObjectID AND b.MapID = expected.MapID
    AND b.WorldMapAreaId = expected.WorldMapAreaId AND b.Floor = expected.Floor
    AND b.Priority = expected.Priority AND b.Flags = expected.Flags AND b.WorldEffectID = expected.WorldEffectID
    AND b.PlayerConditionID = expected.PlayerConditionID AND b.WoDUnk1 = expected.WoDUnk1
    AND b.AlwaysAllowMergingBlobs = expected.AlwaysAllowMergingBlobs
WHERE NOT EXISTS (
    SELECT 1 FROM quest_poi_points AS current WHERE current.QuestID = p.QuestID AND current.Idx1 = p.Idx1
) AND NOT EXISTS (
    SELECT 1 FROM quest_poi AS other
    WHERE other.QuestID = p.QuestID AND other.Idx1 = p.Idx1 AND other.BlobIndex <> expected.BlobIndex
);

DROP TEMPORARY TABLE argus_poi_coordinates;
DROP TEMPORARY TABLE argus_poi_definitions;
COMMIT;
